<?php
namespace App\Filament\Pages;
use Filament\Pages\Page; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Hash;
class ChangePassword extends Page
{ protected static string|\BackedEnum|null $navigationIcon='heroicon-o-lock-closed'; protected string $view='filament.pages.change-password'; protected static ?string $navigationLabel='Change Password'; protected static ?string $title='Change Password'; protected static ?int $navigationSort=1; protected static ?string $slug='change-password'; public string $currentPassword=''; public string $newPassword=''; public string $confirmPassword=''; public bool $success=false; public static function shouldRegisterNavigation(): bool { return auth('web')->check(); } public function mount(): void { abort_unless(Auth::guard('web')->check(),403); } public function save(): void { $this->success=false; $this->validate(['currentPassword'=>'required|string','newPassword'=>'required|string|min:8|max:64|different:currentPassword','confirmPassword'=>'required|same:newPassword']); $user=Auth::guard('web')->user(); if(!Hash::check($this->currentPassword,$user->password)){ $this->addError('currentPassword','The current password is incorrect.'); return; } $user->forceFill(['password'=>Hash::make($this->newPassword),'must_change_password'=>false])->save(); activity()->causedBy($user)->log('Portal password changed successfully.'); $this->reset(['currentPassword','newPassword','confirmPassword']); $this->success=true; $this->redirect('/dashboard'); } }
